package com.ligamunicipal.api.web;
import com.ligamunicipal.api.model.*; import com.ligamunicipal.api.service.LigaService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class LigaController { private final LigaService s; public LigaController(LigaService s){this.s=s;}
@PostMapping("/auth/login") public Usuario login(@RequestBody LoginRequest request){return s.login(request.email(),request.password());}
@GetMapping("/equipos") public List<Equipo> equipos(@RequestHeader("X-User-Id") UUID usuarioId){return s.equipos(usuarioId);} @PostMapping("/equipos") public Equipo crear(@Valid @RequestBody CrearEquipoRequest request,@RequestHeader("X-User-Id") UUID usuarioId){return s.crearEquipo(request.equipo(),usuarioId,request.esJugadorReal());} @GetMapping("/equipos/{id}/dashboard") public Map<String,Object> dashboard(@PathVariable UUID id,@RequestHeader("X-User-Id") UUID usuarioId){s.requireAdmin(id,usuarioId);return s.dashboard(id);} @GetMapping("/equipos/{id}/plantilla") public List<JugadorPlantilla> plantilla(@PathVariable UUID id,@RequestHeader("X-User-Id") UUID usuarioId){s.requireAdmin(id,usuarioId);return s.plantilla(id);} @PostMapping("/equipos/{id}/plantilla") public JugadorPlantilla jugador(@PathVariable UUID id,@Valid @RequestBody JugadorPlantilla j,@RequestHeader("X-User-Id") UUID usuarioId){return s.crearJugador(id,j,usuarioId);} @GetMapping("/equipos/{id}/partidos") public List<PartidoJornada> partidos(@PathVariable UUID id,@RequestHeader("X-User-Id") UUID usuarioId){s.requireAdmin(id,usuarioId);return s.jornadas(id);} @PostMapping("/equipos/{id}/partidos") public PartidoJornada partido(@PathVariable UUID id,@Valid @RequestBody PartidoJornada p,@RequestHeader("X-User-Id") UUID usuarioId){return s.crearPartido(id,p,usuarioId);} @PostMapping("/equipos/{id}/precios/encuesta") public Equipo encuesta(@PathVariable UUID id,@RequestParam boolean abierta,@RequestHeader("X-User-Id") UUID usuarioId){return abierta?s.abrirEncuesta(id,usuarioId):s.cerrarEncuesta(id,usuarioId);} @PostMapping("/equipos/{id}/jugadores/{jugadorId}/precio") public PropuestaPrecioInicial precio(@PathVariable UUID id,@PathVariable UUID jugadorId,@RequestBody PrecioRequest request,@RequestHeader("X-User-Id") UUID usuarioId){return s.proponerPrecio(id,jugadorId,request.valor(),usuarioId);} @PostMapping("/partidos/{partidoId}/jugadores/{jugadorId}/asistencia") public AsistenciaPartido asistencia(@PathVariable UUID partidoId,@PathVariable UUID jugadorId,@RequestParam EstadoAsistencia estado,@RequestHeader("X-User-Id") UUID usuarioId){return s.asistencia(partidoId,jugadorId,estado,usuarioId);} @PostMapping("/partidos/{partidoId}/alineaciones/{miembroId}") public AlineacionFantasy alineacion(@PathVariable UUID partidoId,@PathVariable UUID miembroId,@RequestBody AlineacionFantasy a,@RequestHeader("X-User-Id") UUID usuarioId){return s.guardarAlineacion(partidoId,miembroId,a,usuarioId);} @PostMapping("/votos") public VotoJornada voto(@RequestBody VotoJornada v){return s.votar(v);} }
record LoginRequest(String email,String password) {}
record CrearEquipoRequest(Equipo equipo,boolean esJugadorReal) {}
record PrecioRequest(java.math.BigDecimal valor) {}
